  "studio.voiceClone.script.professionalDuration": "±90 seconden",
  "studio.voiceClone.script.quickBody":
    "Hallo! Ben je klaar voor vandaag?\nIk tel even mee: 3, 7 en 12.\nHet is kwart over drie — perfect timing.\nIk voel me vrolijk en rustig tegelijk.\nKorte zin. En nu een iets langere zin over een recept van €4,50 dat je in 20 minuten maakt.",
  "studio.voiceClone.script.normalBody":
    "Goedemorgen! Welkom bij onze keuken.\nStel je voor: 5 personen, 2 gerechten, 1 grote tafel.\nHet kost €12,80 en duurt ongeveer 45 minuten.\nHoe voel je je vandaag — nieuwsgierig, enthousiast, of juist kalm?\nKorte zin. Nu een langere zin over verse ingrediënten die je om 18:30 kunt serveren met een glimlach.",
  "studio.voiceClone.script.professionalBody":
    "Welkom. Vandaag nemen we je mee achter de schermen.\nWe beginnen om 09:00, werken in 3 fases, en ronden af rond 17:45.\nHet budget is €250 — inclusief 15% voor verse producten.\nVoel je de energie? En ook de rust tussen de zinnen?\nKorte zin.\nEen langere zin legt uit waarom community, smaak en verhalen samen één herkenbare stem vormen — precies wat je nodig hebt voor video's, tutorials en merkhosts.",
  "studio.voiceClone.quality.title": "Geschatte opnamekwaliteit",
